public boolean isOneEditDistance(String s, String t) {
    int m = s.length();
    int n = t.length();
    if (Math.abs(m - n) > 1) {
        return false;
    }
    int diffCount = 0;
    for (int i = 0; i < Math.min(m, n); ++i) {
        if (s.charAt(i) != t.charAt(i)) {
            diffCount++;
            if (diffCount > 1) {
                return false;
            }
        }
    }
    return Math.abs(m - n) + diffCount == 1;
}

