import java.util.Arrays;

public class Solution {
    public int minCost(int[][] costs) {
        if (costs == null || costs.length == 0) return 0;

        int n = costs.length;
        int k = costs[0].length;

        // Use a single array to store the minimum cost to reach each house
        int[] prevMin = new int[k];
        int[] currMin = new int[k];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < k; j++) {
                int minCost = Integer.MAX_VALUE;
                for (int l = 0; l < k; l++) {
                    if (l == j) continue;
                    minCost = Math.min(minCost, prevMin[l]);
                }
                currMin[j] = costs[i][j] + minCost;
            }
            // Swap arrays to reuse memory
            int[] temp = prevMin;
            prevMin = currMin;
            currMin = temp;
        }
        return Arrays.stream(prevMin).min().getAsInt();
    }

