    // Use a Set to keep track of characters with odd counts
    Set<Character> oddChars = new HashSet<>();
    for (char c : s.toCharArray()) {
        if (c == ' ') continue; // Ignore spaces
        if (oddChars.contains(c)) {
            oddChars.remove(c);
        } else {
            oddChars.add(c);
        }
    }
    return oddChars.size() <= 1;
}

